import * as React from "react"
import { TextInput } from "react-native"
import type { UnistylesVariants } from "react-native-unistyles"
import { inputStyles, useInputVariants } from "../../theme/variants/input"
import { layoutToStyle, type LayoutProps } from "./layout"

export type InputProps = {
  value?: string
  defaultValue?: string
  placeholder?: string
  layout?: LayoutProps
  onChangeText?: (text: string) => void
} & UnistylesVariants<typeof inputStyles>

export function Input({
  value,
  defaultValue,
  placeholder,
  disabled,
  layout,
  onChangeText,
}: InputProps) {
  useInputVariants({
    disabled,
  })

  return (
    <TextInput
      value={value}
      defaultValue={defaultValue}
      placeholder={placeholder}
      editable={!disabled}
      onChangeText={onChangeText}
      style={[inputStyles.root, layoutToStyle(layout)]}
    />
  )
}

import type { ViewStyle } from "react-native"

export type LayoutProps = {
  margin?: ViewStyle["margin"]
  width?: ViewStyle["width"]
  maxWidth?: ViewStyle["maxWidth"]
}

export function layoutToStyle(layout?: LayoutProps): ViewStyle | undefined {
  if (!layout) return undefined
  const style: ViewStyle = {}
  if (layout.margin !== undefined) style.margin = layout.margin
  if (layout.width !== undefined) style.width = layout.width
  if (layout.maxWidth !== undefined) style.maxWidth = layout.maxWidth
  return Object.keys(style).length > 0 ? style : undefined
}

export type NativeTheme = {
  colors: {
    bg: {
      surface: string
      accent: string
      muted: string
    }
    fg: {
      default: string
      muted: string
      onAccent: string
    }
    border: {
      default: string
      focus: string
    }
  }
  space: {
    control: {
      px: number
      py: number
      gap: number
    }
  }
  radius: {
    control: number
  }
  typography: {
    label: {
      fontSize: number
    }
  }
  opacity: {
    disabled: number
  }
}

/** Lib playground demo only. Client apps must supply their own theme values. */
export const defaultDemoTheme = {
  colors: {
    bg: {
      surface: "#ffffff",
      accent: "#18181b",
      muted: "#f4f4f5",
    },
    fg: {
      default: "#18181b",
      muted: "#71717a",
      onAccent: "#fafafa",
    },
    border: {
      default: "#e4e4e7",
      focus: "#2563eb",
    },
  },
  space: {
    control: {
      px: 12,
      py: 8,
      gap: 8,
    },
  },
  radius: {
    control: 8,
  },
  typography: {
    label: {
      fontSize: 14,
    },
  },
  opacity: {
    disabled: 0.5,
  },
} satisfies NativeTheme
